/**
 * Högtider & familjehändelser (0.29, R02-A04-T05): birthdays, engagement and wedding, christening
 * and naming, studenten and degrees, jubilees, funerals and family gatherings. People have their own
 * arms (a pose never shows a third arm); the person a word is about is in colour and the others are
 * muted or grey; abstract words are small symbolic scenes.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { HL, T, balloon, bubble, cup, envelope, heart, note, sun, thought } from './people';
