type Pt = [number, number];
type Mood = 'smile' | 'frown' | 'sad' | 'shock' | 'laugh' | 'calm' | 'shout' | 'sing' | 'sleep' | 'neutral' | 'cry';
type Fig = {
  x?: number; h?: number; y?: number; top?: string; bottom?: string; hair?: string; long?: boolean; grey?: boolean; mood?: Mood;
  l?: Pt[]; r?: Pt[]; skirt?: string; legs?: 'stand' | 'sit'; gown?: string; veil?: boolean; tie?: string; collar?: boolean;
  hat?: string; crown?: boolean; scap?: boolean; tiara?: boolean; sash?: string; cape?: string; lei?: boolean; coat?: boolean;
};

