const YEL = '#f2c94c';

/** Face on a head centred at (0, -56), radius 10 (figure coordinates). */
function face(m: Mood, sk: string): Svg {
  const ink = C.ink;
  const eyes = m === 'sleep' || m === 'calm' ? path('M-5.5 -56 Q-3.6 -54.4 -1.8 -56 M1.8 -56 Q3.6 -54.4 5.5 -56', 'none', ink, 1.3)
    : m === 'laugh' || m === 'sing' ? path('M-5.5 -55 Q-3.6 -58 -1.8 -55 M1.8 -55 Q3.6 -58 5.5 -55', 'none', ink, 1.3)
    : m === 'cry' ? path('M-5.5 -57 Q-3.6 -54 -1.8 -57 M1.8 -57 Q3.6 -54 5.5 -57', 'none', ink, 1.3)
    : m === 'shock' ? all(circle(-3.4, -56, 1.8, C.white, ink, 0.9), circle(3.4, -56, 1.8, C.white, ink, 0.9), circle(-3.4, -56, 0.8, ink, null), circle(3.4, -56, 0.8, ink, null))
    : all(circle(-3.4, -56, 1.2, ink, null), circle(3.4, -56, 1.2, ink, null));
  const brows = m === 'shout' ? line('M-6 -60.5 L-1.6 -58.6 M6 -60.5 L1.6 -58.6', ink, 1.4)
    : m === 'frown' || m === 'sad' || m === 'cry' ? line('M-6 -58.6 L-1.8 -59.8 M6 -58.6 L1.8 -59.8', ink, 1.1) : '';
  const mouth = m === 'frown' || m === 'sad' || m === 'cry' ? path('M-3 -50 Q0 -52.6 3 -50', 'none', ink, 1.3)
    : m === 'laugh' ? path('M-3.6 -52 Q0 -46 3.6 -52 Z', '#c84a4a', ink, 1)
    : m === 'shout' || m === 'sing' ? ellipse(0, -50.4, 2.4, 2.6, '#c84a4a', ink, 1)
    : m === 'shock' ? ellipse(0, -50.5, 1.6, 2, '#c84a4a', ink, 0.9)
    : m === 'neutral' || m === 'sleep' ? line('M-2.6 -50.6 L2.6 -50.6', ink, 1.2)
    : path('M-3 -51.5 Q0 -48.6 3 -51.5', 'none', ink, 1.3);
  const extra = m === 'cry' ? all(path('M-4 -53 C-5 -50 -3 -49 -3 -51 Z', '#8cc7e8', null), path('M4 -53 C5 -50 3 -49 3 -51 Z', '#8cc7e8', null)) : '';
  return all(circle(0, -55, 7.4, sk, null), eyes, brows, mouth, extra);
}

/** One arm as a sleeve from the shoulder through the given points, with a hand at the end. */
function armOf(pts: Pt[], col: string, sk: string): Svg {
  const d = 'M' + pts.map(([a, b]) => `${a} ${b}`).join(' L');
  const [hx, hy] = pts[pts.length - 1]!;
  return all(line(d, C.ink, 8.4), line(d, col, 5.8), circle(hx, hy, 3.4, sk, C.ink, 1.4));
}

/** Standing (or sitting) person, front view, with its own arms and a mood face; feet on y. */
