const flame = (x: number, y: number, s = 1) => path(`M${x} ${y - 9 * s} C${x + 3.4 * s} ${y - 4 * s} ${x + 2.6 * s} ${y} ${x} ${y} C${x - 2.6 * s} ${y} ${x - 3.4 * s} ${y - 4 * s} ${x} ${y - 9 * s} Z`, YEL, C.orange, 1);
